cd /workspace && node -e "
const fs = require('fs');
const expenses = JSON.parse(fs.readFileSync('data/expenses_q3.json', 'utf8'));

const newExpense = {
  expense_id: 'EX026',
  employee_id: 'E001',
  category: 'travel',
  amount: 1550.00,
  date: '2026-09-22',
  approved: false,
  description: 'Client strategy meeting — San Francisco — 2 nights (Hyatt Regency SF)'
};

expenses.push(newExpense);
fs.writeFileSync('data/expenses_q3.json', JSON.stringify(expenses, null, 2) + '\n');
console.log('Added EX026. Total records:', expenses.length);
"

cd /workspace && node -e "
const expenses = require('./data/expenses_q3.json');

// Show the new entry
const ex026 = expenses.find(e => e.expense_id === 'EX026');
console.log('=== New Entry (EX026) ===');
console.log(JSON.stringify(ex026, null, 2));

// Updated totals
const travel = expenses.filter(e => e.category === 'travel');
const totalAll = expenses.reduce((s, e) => s + e.amount, 0);
const totalTravel = travel.reduce((s, e) => s + e.amount, 0);
console.log('\n=== Updated Totals ===');
console.log('Total records:      ', expenses.length);
console.log('Total expenses:      \$' + totalAll.toFixed(2));
console.log('Travel expenses:     ' + travel.length + ' entries, \$' + totalTravel.toFixed(2));
console.log('Travel % of spend:   ' + (totalTravel/totalAll*100).toFixed(1) + '%');
"
